import * as T from '../vendor/three.module.js';
import {WATER_LEVEL} from './waterways.js?v=13';
const metal=new T.MeshStandardMaterial({color:'#77888d',metalness:.65,roughness:.38}),dark=new T.MeshStandardMaterial({color:'#1c2b35',metalness:.4,roughness:.38}),accent=new T.MeshStandardMaterial({color:'#9bc6bc',metalness:.55,roughness:.32}),glass=new T.MeshStandardMaterial({color:'#315a70',metalness:.85,roughness:.15}),hot=new T.MeshBasicMaterial({color:'#ffad57'});
function box(parent,mat,x,y,z,w,h,d){const m=new T.Mesh(new T.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m;}
export function createMarineKit(car,scene){const root=new T.Group();car.root.add(root);const sides=[],props=[];for(const side of [-1,1]){const part=new T.Group();root.add(part);sides.push(part);box(part,dark,0,.22,0,.58,.5,4.5);box(part,accent,0,.49,0,.61,.1,4.2);const nose=new T.Mesh(new T.SphereGeometry(1,12,8),accent);nose.scale.set(.31,.25,.48);nose.position.set(0,.26,-2.2);part.add(nose);box(part,metal,-side*.27,.38,.8,.45,.12,.2);box(part,metal,-side*.27,.38,-.8,.45,.12,.2);const motor=new T.Mesh(new T.CylinderGeometry(.23,.23,.45,12),dark);motor.rotation.x=Math.PI/2;motor.position.set(0,.2,2.35);part.add(motor);const p=new T.Group();p.position.set(0,.2,2.62);for(let i=0;i<3;i++){const blade=box(p,metal,0,.15,0,.11,.36,.04);blade.rotation.z=i*Math.PI*2/3;}part.add(p);props.push(p);}
 const wake=new T.Group();scene.add(wake);const wm=new T.MeshBasicMaterial({color:'#d6f1e8',transparent:true,opacity:.25,depthWrite:false,side:T.DoubleSide});for(const side of [-1,1]){const m=new T.Mesh(new T.PlaneGeometry(.7,13),wm);m.rotation.x=-Math.PI/2;m.rotation.z=side*.22;m.position.set(side*2,0,8);wake.add(m);}let blend=0,wheelBlend=0;return {update(s,time,dt){blend+=(+(!!s.boat)-blend)*(1-Math.exp(-dt*4));root.visible=blend>.01;root.scale.y=Math.max(.02,blend);for(let i=0;i<2;i++){sides[i].position.x=(i?1:-1)*(.82+blend*.51);props[i].rotation.z+=s.speed*dt*7;}wheelBlend+=(+(!!s.inWater)-wheelBlend)*(1-Math.exp(-dt*4));for(const wheel of car.wheels){wheel.scale.setScalar(1-wheelBlend*.95);wheel.parent.position.y=.34+wheelBlend*.28;}wake.visible=!!s.inWater&&Math.abs(s.speed)>.5;wake.position.set(s.x,WATER_LEVEL+.045,s.z);wake.rotation.y=s.yaw;wm.opacity=Math.min(.32,Math.abs(s.speed)*.035);}};
}
function createFighter(){const root=new T.Group();box(root,metal,0,1,0,1.35,1.15,8);const nose=new T.Mesh(new T.ConeGeometry(.7,3,16),metal);nose.rotation.x=-Math.PI/2;nose.position.set(0,1,-5.3);root.add(nose);const canopy=new T.Mesh(new T.SphereGeometry(1,16,10),glass);canopy.scale.set(.62,.65,1.55);canopy.position.set(0,1.7,-2);root.add(canopy);for(const side of [-1,1]){const wing=box(root,metal,side*2.6,.85,.6,4.7,.14,2.1);wing.rotation.y=side*.4;const tail=box(root,dark,side*1.3,1,3.8,2.4,.12,1.2);tail.rotation.y=side*.3;const fin=box(root,metal,side*.55,2.0,3.6,.12,1.9,1.8);fin.rotation.z=side*-.15;const engine=new T.Mesh(new T.CylinderGeometry(.4,.4,1.8,12),dark);engine.rotation.x=Math.PI/2;engine.position.set(side*.49,.9,3.6);root.add(engine);const flame=new T.Mesh(new T.ConeGeometry(.3,1.8,12),hot);flame.rotation.x=Math.PI/2;flame.position.set(side*.49,.9,5.1);root.add(flame);box(root,hot,side*4.8,.9,1.6,.12,.08,.25);}return root;}
export function createAirModels(scene,air,effects){const fighters=Array.from({length:3},()=>{const m=createFighter();scene.add(m);m.visible=false;return m;}),missiles=Array.from({length:6},()=>{const m=new T.Group(),body=new T.Mesh(new T.CylinderGeometry(.1,.12,1.5,8),metal);body.rotation.x=Math.PI/2;m.add(body);const flame=new T.Mesh(new T.ConeGeometry(.2,1.7,8),hot);flame.rotation.x=Math.PI/2;flame.position.z=1.4;m.add(flame);scene.add(m);m.visible=false;return m;});let trail=0;return {update(dt){const alive=air.alive;for(let i=0;i<3;i++){const f=alive[i],m=fighters[i];m.visible=!!f;if(f){m.position.set(f.x,f.y,f.z);m.rotation.order='YXZ';m.rotation.set(f.pitch,f.yaw,f.bank);}}trail+=dt;for(let i=0;i<6;i++){const m=missiles[i],p=air.missiles[i];m.visible=!!p;if(p){m.position.set(p.x,p.y,p.z);m.rotation.order='YXZ';m.rotation.set(p.pitch,p.yaw,0);if(trail>.045)effects.trail(p);}}if(trail>.045)trail=0;}};}
